<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>GALAGA</title>
<style>
  html,body{margin:0;padding:0;height:100%;background:#000;overflow:hidden}
  #wrap{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}
  canvas{background:#000;image-rendering:pixelated;image-rendering:crisp-edges}
</style>
</head>
<body>
<div id="wrap"><canvas id="cv" width="224" height="288"></canvas></div>
<script>
"use strict";
/* ================= GALAGA clone - single file ================= */
const W=224,H=288,STEP=1000/60;
const cv=document.getElementById('cv'),ctx=cv.getContext('2d');
function resize(){ // integer scaling for crisp pixels
  const s=Math.max(1,Math.floor(Math.min(innerWidth/W,innerHeight/H)));
  cv.style.width=(W*s)+'px';cv.style.height=(H*s)+'px';
}
addEventListener('resize',resize);resize();

/* ================= audio (Web Audio, synthesized) ================= */
let AC=null,master=null,beamSnd=null,muted=false;
function initAudio(){ // called on first key press (browser autoplay policy)
  if(AC)return;
  try{
    AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain();master.gain.value=muted?0:0.25;master.connect(AC.destination);
  }catch(e){}
}
function tone(f0,dur,type,vol,f1,delay){
  if(!AC||muted)return;
  const t=AC.currentTime+(delay||0);
  const o=AC.createOscillator(),g=AC.createGain();
  o.type=type||'square';o.frequency.setValueAtTime(f0,t);
  if(f1)o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);
  g.gain.setValueAtTime(vol||0.4,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g);g.connect(master);o.start(t);o.stop(t+dur+0.02);
}
function noiseSnd(dur,vol,delay){
  if(!AC||muted)return;
  const t=AC.currentTime+(delay||0),n=Math.floor(AC.sampleRate*dur);
  const buf=AC.createBuffer(1,n,AC.sampleRate),d=buf.getChannelData(0);
  for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*(1-i/n);
  const s=AC.createBufferSource(),g=AC.createGain();
  s.buffer=buf;g.gain.setValueAtTime(vol||0.5,t);g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(g);g.connect(master);s.start(t);
}
const sShoot   =()=>tone(880,0.09,'square',0.25,180);
const sEnemyDie=()=>{noiseSnd(0.22,0.4);tone(220,0.18,'sawtooth',0.25,60);};
const sBossHit =()=>{tone(330,0.08,'triangle',0.5,220);noiseSnd(0.08,0.2);};
const sPlayerDie=()=>{noiseSnd(0.7,0.7);tone(160,0.6,'sawtooth',0.35,40);tone(90,0.7,'square',0.25,30,0.05);};
const sCapture =()=>{tone(600,0.5,'sawtooth',0.3,80);};
const sDock    =()=>{tone(400,0.1,'square',0.3,800);tone(800,0.15,'square',0.3,1600,0.1);};
const sExtra   =()=>{tone(660,0.08,'square',0.3);tone(880,0.08,'square',0.3,0,0.09);tone(1320,0.12,'square',0.3,0,0.18);};
function sBeamStart(){
  if(!AC||muted||beamSnd)return;
  const o=AC.createOscillator(),g=AC.createGain(),l=AC.createOscillator(),lg=AC.createGain();
  o.type='sawtooth';o.frequency.value=55;l.type='sine';l.frequency.value=24;lg.gain.value=35;
  l.connect(lg);lg.connect(o.frequency);g.gain.value=0.22;
  o.connect(g);g.connect(master);o.start();l.start();
  beamSnd={o,g,l};
}
function sBeamStop(){if(beamSnd){try{beamSnd.o.stop();beamSnd.l.stop();}catch(e){}beamSnd=null;}}
/* Galaga-style opening jingle */
function jingle(){
  if(!AC)return;
  const E5=659.25,E3=164.81,E4=329.63,B4=493.88,G4=392.00;
  const mel=[E5,E3,E4,B4,G4,E4,B4,G4,E4,B4,G4,E5];
  const durs=[.11,.11,.11,.11,.11,.11,.11,.11,.22,.11,.11,.33];
  let t=0;
  for(let i=0;i<mel.length;i++){tone(mel[i],durs[i]*0.95,'square',0.3,null,t);t+=durs[i];}
}

/* ================= 5x7 bitmap font ================= */
const FONT={
'A':["01110","10001","10001","11111","10001","10001","10001"],
