'%':["10001","10010","00100","00100","01000","10001","10001"],
'/':["00001","00010","00010","00100","01000","01000","10000"]
};
function drawText(s,x,y,color,scale){
  scale=scale||1;ctx.fillStyle=color;s=s.toUpperCase();
  for(let c=0;c<s.length;c++){
    const g=FONT[s[c]];if(!g)continue;
    for(let r=0;r<7;r++)for(let i=0;i<5;i++)
      if(g[r][i]==='1')ctx.fillRect(x+c*6*scale+i*scale,y+r*scale,scale,scale);
  }
}
function textW(s,scale){return s.length*6*(scale||1);}

/* ================= pixel sprites ================= */
const PAL={
  '1':'#3838ff','2':'#ffd23b','3':'#ff3b3b','4':'#3bd23b',
  '5':'#b03bff','6':'#ffffff','7':'#3befff','8':'#ff8b2b','9':'#ff4bd8'
};
const SPR={
player:[
"......66......",
"......66......",
".....6666.....",
".....1661.....",
"....116611....",
"....116611....",
"...11366311...",
"..1113663111..",
".111136631111.",
"11111366311111",
"11111366311111",
"11111366311111",
".111136631111.",
"..1...66...1.."],
zakoA:[
".22........22.",
".22........22.",
".222......222.",
"..2211111122..",
