"...22111122...",
"....111111....",
"..1121111211..",
"...11111111...",
"....111111....",
".....1..1....."],
goeiA:[
".33........33.",
".3333....3333.",
".333611116333.",
"..3331111333..",
"...33111133...",
"...31166113...",
"....311113....",
".....3..3....."],
goeiB:[
"...3......3...",
"...33....33...",
"...33611633...",
"....311113....",
"...33111133...",
"....316613....",
"....311113....",
"......33......"],
bossA:[
"..11........11..",
"..1111....1111..",
"...1114444111...",
"...446444644....",
"...444444444....",
"....44444444....",
"....14444441....",
".....144441.....",
"......1441......",
".......11.......",
"....11....11....",
".....1....1....."],
bossB:[
"......1111......",
".....111111.....",
"...1144444411...",
"...446444644....",
"...444444444....",
"....44444444....",
