".....1....1....."],
flag:[
".333333.",
".33333..",
".33.....",
"..6.....",
"..6.....",
"..6....."]
};
/* variant colour remaps */
const VAR={
  playerBoss:{'6':'#ff3b3b','1':'#ff8b2b','3':'#ffffff'},   // captured fighter (red)
  bossDmg   :{'1':'#b03bff','4':'#3838ff'}                  // damaged boss Galaga
};
const spriteCache={};
function getSprite(name,variant){
  const key=name+'|'+(variant||'');
  if(spriteCache[key])return spriteCache[key];
  const rows=SPR[name],w=rows[0].length,h=rows.length;
  const c=document.createElement('canvas');c.width=w;c.height=h;
  const g=c.getContext('2d'),map=variant?VAR[variant]:null;
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){
    const ch=rows[y][x];if(ch==='.')continue;
    g.fillStyle=(map&&map[ch])||PAL[ch]||'#fff';
    g.fillRect(x,y,1,1);
  }
  spriteCache[key]=c;return c;
}
function blit(name,x,y,variant){
  const s=getSprite(name,variant);
  ctx.drawImage(s,Math.round(x-s.width/2),Math.round(y-s.height/2));
}

/* ================= starfield ================= */
const STAR_COLS=['#ffffff','#ffffff','#ffffff','#3befff','#ff4bd8','#ffd23b','#3bd23b'];
const stars=[];
for(let i=0;i<90;i++)stars.push({
  x:Math.random()*W,y:Math.random()*H,
  s:(i%3)+0.4,c:STAR_COLS[(Math.random()*STAR_COLS.length)|0],
  tw:Math.random()*Math.PI*2
});
function updateStars(){for(const st of stars){st.y+=st.s*0.5;if(st.y>=H){st.y-=H;st.x=Math.random()*W;}}}
function drawStars(){
  for(const st of stars){
    const b=0.45+0.55*Math.abs(Math.sin(st.tw+G.t*0.05));
    ctx.globalAlpha=b;ctx.fillStyle=st.c;ctx.fillRect(st.x|0,st.y|0,1,1);
  }
  ctx.globalAlpha=1;
}

/* ================= paths (Catmull-Rom polylines) ================= */
function cr(p0,p1,p2,p3,t){
  const t2=t*t,t3=t2*t;
  return{
    x:0.5*((2*p1.x)+(-p0.x+p2.x)*t+(2*p0.x-5*p1.x+4*p2.x-p3.x)*t2+(-p0.x+3*p1.x-3*p2.x+p3.x)*t3),
    y:0.5*((2*p1.y)+(-p0.y+p2.y)*t+(2*p0.y-5*p1.y+4*p2.y-p3.y)*t2+(-p0.y+3*p1.y-3*p2.y+p3.y)*t3)
  };
}
function makePath(pts){
  const P=[pts[0]].concat(pts,[pts[pts.length-1]]);
  const smp=[],cum=[0];
  for(let i=1;i<P.length-2;i++)
    for(let t=0;t<1;t+=0.1)smp.push(cr(P[i-1],P[i],P[i+1],P[i+2],t));
  smp.push(pts[pts.length-1]);
  let len=0;
  for(let i=1;i<smp.length;i++){
    len+=Math.hypot(smp[i].x-smp[i-1].x,smp[i].y-smp[i-1].y);cum.push(len);
  }
  return{
    len,
    at(d){
      if(d<=0)return smp[0];
      if(d>=len)return smp[smp.length-1];
      let lo=0,hi=cum.length-1;
      while(lo<hi-1){const m=(lo+hi)>>1;if(cum[m]<=d)lo=m;else hi=m;}
      const t=(d-cum[lo])/((cum[hi]-cum[lo])||1);
      return{x:smp[lo].x+(smp[hi].x-smp[lo].x)*t,y:smp[lo].y+(smp[hi].y-smp[lo].y)*t};
    }
  };
}

/* ================= game state ================= */
let G=null;
const keys={};
function loadHi(){try{return +localStorage.getItem('galaga.hi')||0;}catch(e){return 0;}}
function saveHi(){try{localStorage.setItem('galaga.hi',G.hi);}catch(e){}}

function boot(){
  G={mode:'title',t:0,score:0,hi:loadHi(),lives:2,stage:1,shots:0,hits:0,
     nextExtra:20000,pause:false,
     enemies:[],pBullets:[],eBullets:[],expl:[],ships:[],
     player:{x:112,y:252,alive:true,dual:false,captured:false,invul:0,fireCd:0},
     fmt:{complete:false},groups:[],spawnT:0,
     diveT:180,msg:null,overlayT:0,
     chWave:0,chWaveActive:false,chWaveHits:0,chWaveDone:0,chHits:0,chBonus:0,
     beam:null};
}
boot();

function isChallenge(s){return s>=3&&(s-3)%4===0;}
function setHi(){if(G.score>G.hi){G.hi=G.score;saveHi();}}

/* formation geometry (10 columns, 5 rows) */
const FMT_TOP=50,FMT_CX=112,COLS=16,ROWS=13;
function slotXY(row,col){
  const f=G.fmt;
  return{x:FMT_CX+(col-4.5)*COLS*f.scale+f.offX,
         y:FMT_TOP+row*ROWS*f.scale+f.offY};
}
function fmtUpdate(){
  const t=G.t,f=G.fmt;
  f.complete=G.enemies.length>0&&G.enemies.every(e=>e.state==='formation');
  const amp=f.complete?5:18;
  f.offX=Math.sin(t*0.018)*amp;
  f.scale=f.complete?1+0.07*Math.sin(t*0.028):1;
  f.offY=f.complete?3*Math.sin(t*0.028):0;
}

/* entry path patterns */
function entryPattern(pi,slot){
  const s={x:slot.x,y:slot.y};
  const pats=[
    [{x:-24,y:140},{x:40,y:120},{x:90,y:60},{x:150,y:55},{x:175,y:105},{x:130,y:150},{x:75,y:120},s],
    [{x:248,y:140},{x:184,y:120},{x:134,y:60},{x:74,y:55},{x:49,y:105},{x:94,y:150},{x:149,y:120},s],
    [{x:-24,y:310},{x:35,y:190},{x:85,y:120},{x:125,y:160},{x:160,y:110},s],
    [{x:248,y:310},{x:189,y:190},{x:139,y:120},{x:99,y:160},{x:64,y:110},s],
    [{x:-24,y:60},{x:60,y:70},{x:120,y:40},{x:185,y:80},{x:140,y:130},{x:90,y:100},s]
  ];
  return makePath(pats[pi%5]);
}
function challengePath(dir,i){
  const y0=55+i*3;
  const p=dir>0?
    [{x:-24,y:y0},{x:45,y:y0},{x:95,y:y0-25},{x:150,y:y0+30},{x:105,y:y0+70},{x:65,y:y0+30},{x:115,y:y0-5},{x:180,y:y0+10},{x:252,y:y0+35}]:
    [{x:252,y:y0},{x:183,y:y0},{x:133,y:y0-25},{x:78,y:y0+30},{x:123,y:y0+70},{x:163,y:y0+30},{x:113,y:y0-5},{x:48,y:y0+10},{x:-28,y:y0+35}];
  return makePath(p);
}

/* build the 5 entry groups (40 enemies) */
function buildGroups(){
  const mk=(row,col,type,pid)=>({row,col,type,pid});
  const g=[];
  g.push([mk(0,3,'boss',0),mk(0,4,'boss',0),mk(0,5,'boss',0),mk(0,6,'boss',0),
          mk(1,1,'goei',0),mk(1,2,'goei',0),mk(1,3,'goei',0),mk(1,4,'goei',0)]);
  g.push([mk(1,5,'goei',1),mk(1,6,'goei',1),mk(1,7,'goei',1),mk(1,8,'goei',1),
          mk(2,1,'goei',1),mk(2,2,'goei',1),mk(2,3,'goei',1),mk(2,4,'goei',1)]);
  g.push([mk(2,5,'goei',2),mk(2,6,'goei',2),mk(2,7,'goei',2),mk(2,8,'goei',2),
          mk(3,0,'zako',2),mk(3,1,'zako',2),mk(3,2,'zako',2),mk(3,3,'zako',2)]);
  g.push([mk(3,4,'zako',3),mk(3,5,'zako',3),mk(3,6,'zako',3),mk(3,7,'zako',3),
          mk(3,8,'zako',3),mk(3,9,'zako',3),mk(4,0,'zako',3),mk(4,1,'zako',3)]);
  g.push([mk(4,2,'zako',4),mk(4,3,'zako',4),mk(4,4,'zako',4),mk(4,5,'zako',4),
          mk(4,6,'zako',4),mk(4,7,'zako',4),mk(4,8,'zako',4),mk(4,9,'zako',4)]);
  return g;
}
function makeEnemy(spec){
  const slot=slotXY.bind(null)(); // placeholder not used
  return{
    type:spec.type,row:spec.row,col:spec.col,
    state:'entering',d:0,speed:2.05,
    x:0,y:-30,hp:spec.type==='boss'?2:1,
    ft:(Math.random()*30)|0,captive:null,escorts:null,boss:null,off:null,
    fireT:60+((Math.random()*120)|0)
  };
}
function startStage(){
  G.enemies=[];G.pBullets=[];G.eBullets=[];G.expl=[];G.ships=[];G.beam=null;
  sBeamStop();
  G.groups=buildGroups();G.spawnT=0;G.diveT=200;
  G.fmt={complete:false,offX:0,offY:0,scale:1};
  G.player={x:112,y:252,alive:true,dual:false,captured:false,invul:60,fireCd:0};
  G.chWave=0;G.chWaveActive=false;G.chWaveHits=0;G.chWaveDone=0;G.chHits=0;G.chBonus=0;
}

/* ================= helpers ================= */
function addExpl(x,y,big){G.expl.push({x,y,t:0,big:!!big});}
function score(n){
  G.score+=n;setHi();
  if(G.score>=G.nextExtra){G.lives++;G.nextExtra+=70000;sExtra();}
}
function fireEB(x,y,aimed){
  if(G.eBullets.length>=8)return;
  let vx=0,vy=2.2;
  if(aimed){
    const dx=G.player.x-x,dy=G.player.y-y,d=Math.hypot(dx,dy)||1;
    vx=dx/d*1.9;vy=dy/d*1.9;
  }
  G.eBullets.push({x,y,vx,vy});
}
function playerFire(){
  const p=G.player;
  if(pBulletsOnScreen()>=2||p.fireCd>0)return;
  if(p.dual){G.pBullets.push({x:p.x-8,y:p.y-8});G.pBullets.push({x:p.x+8,y:p.y-8});G.shots+=2;}
  else{G.pBullets.push({x:p.x,y:p.y-8});G.shots+=1;}
  p.fireCd=10;sShoot();
}
function pBulletsOnScreen(){return G.pBullets.length;}

/* ================= diving ================= */
function divePath(e,targetY){
  const px=G.player.x;
  const sx=e.x,sy=e.y;
  const jx=(Math.random()*2-1)*30;
  if(targetY!==undefined)
    return makePath([{x:sx,y:sy},{x:sx+(sx<112?-16:16),y:sy+14},{x:targetX(e),y:targetY}]);
  return makePath([{x:sx,y:sy},{x:sx+(sx<112?-18:18),y:sy+16},
                   {x:px+jx,y:sy+65},{x:px+(Math.random()*2-1)*60,y:H+30}]);
}
function targetX(e){return Math.max(24,Math.min(W-24,G.player.x+(Math.random()*40-20)));}
function startDive(e,mode){
  e.state='diving';e.d=0;
  e.path=divePath(e);
  e.fireT=10+((Math.random()*20)|0);
  if(mode==='beam'){e.state='beamDive';e.path=divePath(e,96);}
}
function launchGroup(gi){
  const spec=G.groups[gi];
  spec.forEach((sp,i)=>{
    const e=makeEnemy(sp);
    const slot={x:FMT_CX+(sp.col-4.5)*COLS,y:FMT_TOP+sp.row*ROWS};
    e.slot=slot;
    const pid=(sp.pid+gi)%5;
    e.path=entryPattern(pid,slot);
    e.delay=i*7;
    G.enemies.push(e);
  });
}
function scheduleDive(){
  const p=G.player;
  if(!p.alive||p.captured)return;
  const cand=G.enemies.filter(e=>e.state==='formation');
  if(!cand.length)return;
  const stage=G.stage;
  const bosses=cand.filter(e=>e.type==='boss');
  const anyCaptive=G.enemies.some(e=>e.type==='boss'&&e.captive);
  // tractor beam attempt: boss without captive
  if(!anyCaptive&&bosses.length&&Math.random()<Math.min(0.55,0.2+stage*0.05)){
    const b=bosses[(Math.random()*bosses.length)|0];
    startDive(b,'beam');
    return;
  }
  // boss dive with butterfly escorts
  if(bosses.length&&Math.random()<Math.min(0.5,0.15+stage*0.04)){
    const b=bosses[(Math.random()*bosses.length)|0];
    const esc=cand.filter(e=>e.type==='goei'&&Math.abs(e.row-b.row)<=1&&Math.abs(e.col-b.col)<=2).slice(0,2);
    if(esc.length){
      b.escorts=esc;b.escortAlive=esc.length;
      esc.forEach((s,i)=>{
        s.state='escort';s.boss=b;
        s.off={x:(i===0?-1:1)*16*(esc.length===1?0:(esc.indexOf(s)===0?-1:1))||0,y:16};
      });
      // fix offsets: symmetric around boss
      if(esc.length===2){esc[0].off={x:-16,y:16};esc[1].off={x:16,y:16};}
      else esc[0].off={x:(Math.random()<0.5?-16:16),y:16};
      startDive(b,'attack');
      return;
    }
  }
  const e=cand[(Math.random()*cand.length)|0];
  startDive(e,'attack');
}

/* ================= player death / capture ================= */
function killPlayer(){
  const p=G.player;
  if(!p.alive||p.invul>0||p.captured)return;
  sPlayerDie();
  if(p.dual){ // lose only the half that was hit (handled by caller setting p.dual=false already)
    p.alive=true;
  }else{
    p.alive=false;p.respawnT=100;
    addExpl(p.x,p.y,true);
    loseLife();
  }
}
function loseLife(){
  if(G.lives>0){G.lives--;}
  else{G.lives=0;G.mode='gameover';G.overlayT=0;sBeamStop();G.beam=null;}
}
function respawnCheck(){
  const p=G.player;
  if(!p.alive&&G.mode==='play'){
    if(p.respawnT>0)p.respawnT--;
    else{p.alive=true;p.x=112;p.invul=90;p.fireCd=0;}
  }
}
function capturePlayer(boss){
  const p=G.player;
  p.captured=true;p.captureT=0;p.captureBoss=boss;
  sCapture();
}
function finishCapture(boss){
  const p=G.player;
  boss.captive=true;p.captured=false;p.alive=false;p.respawnT=90;
  loseLife();
}

/* ================= enemy kill / scoring ================= */
function enemyScore(e){
  const diving=e.state!=='formation';
  if(e.type==='zako')return diving?100:50;
  if(e.type==='goei')return diving?160:80;
  // boss
  if(!diving)return 150;
  const alive=(e.escorts||[]).filter(s=>!s.dead&&(s.state==='diving'||s.state==='escort'||s.state==='reentry')).length;
  if(alive>=2)return 1600;
  if(alive===1)return 800;
  return 400;
}
function killEnemy(e,hitByPlayer){
  e.dead=true;
  addExpl(e.x,e.y,e.type==='boss');
  if(e.type==='boss'&&e.hp>1){ // first hit on boss: damage, no death
    return;
  }
  if(hitByPlayer){score(enemyScore(e));G.hits++;}
  sEnemyDie();
  // captive handling
  if(e.type==='boss'&&e.captive){
    e.captive=null;
    const inFmt=e.state==='formation';
    G.ships.push({x:e.x,y:e.y-14,vx:0,vy:0,state:inFmt?'hostile':'freed',t:0,fireT:40});
  }
  // escorts of a dying boss keep diving on their own
  if(e.escorts)e.escorts.forEach(s=>{if(!s.dead&&s.state==='escort'){startDive(s,'attack');}});
}

/* ================= update ================= */
function onKey(k){
  initAudio();
  if(k==='m'||k==='M'){muted=!muted;if(master)master.gain.value=muted?0:0.25;if(muted)sBeamStop();return;}
  if(k==='p'||k==='P'){if(G.mode==='play'||G.mode==='challenge')G.pause=!G.pause;return;}
  if(k==='Enter'){
    if(G.mode==='title')startGame();
    else if(G.mode==='results'||(G.mode==='gameover'&&G.overlayT>90))backToTitle();
  }
}
addEventListener('keydown',e=>{
  if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','Enter'].indexOf(e.key)>=0)e.preventDefault();
  if(!e.repeat)onKey(e.key);
  keys[e.key]=true;
});
addEventListener('keyup',e=>{keys[e.key]=false;});

function startGame(){
  const hi=G.hi;
  boot();G.hi=hi;
  G.mode='intro';G.overlayT=0;
  jingle();
}
function backToTitle(){boot();}

function update(){
  G.t++;
  updateStars();
  if(G.pause)return;
  switch(G.mode){
    case 'title':break;
    case 'intro':
      G.overlayT++;
      if(G.overlayT===1&&G.stage>1)jingle();
      if(G.overlayT>110){
        startStage();
        if(isChallenge(G.stage)){G.mode='chintro';G.overlayT=0;}
        else{G.mode='play';}
      }
      break;
    case 'chintro':
      G.overlayT++;
      if(G.overlayT>110){G.mode='challenge';spawnChallengeWave();}
      break;
    case 'play':updatePlay();break;
    case 'challenge':updateChallenge();break;
    case 'gameover':
      G.overlayT++;
      if(G.overlayT>150){G.mode='results';G.overlayT=0;}
      break;
    case 'results':G.overlayT++;break;
  }
}

/* ---- normal stage update ---- */
function updatePlay(){
  const p=G.player;
  fmtUpdate();

  /* spawn entry groups */
  if(G.groups.length){
    G.spawnT--;
    if(G.spawnT<=0){launchGroup(0);G.groups.shift();G.spawnT=150;}
  }

  /* dive scheduler - no dives while player respawning/captured */
  if(p.alive&&!p.captured){
    G.diveT--;
    if(G.diveT<=0){
      scheduleDive();
      const base=Math.max(45,150-G.stage*10);
      G.diveT=base+((Math.random()*60)|0)-30;
    }
  }

  updateEnemies();
  updateShips();
  updateBeam();
  updatePlayer();
  updateBullets();

  /* explosions */
  for(const x of G.expl)x.t++;
  G.expl=G.expl.filter(x=>x.t<(x.big?26:20));

  respawnCheck();

  /* stage cleared? */
  if(G.enemies.length===0&&!G.groups.length&&G.mode==='play'){
    G.stage++;G.mode='intro';G.overlayT=0;
  }
}

function updateEnemies(){
  const p=G.player,stage=G.stage;
  for(const e of G.enemies){
    if(e.dead)continue;
    e.ft++;
    switch(e.state){
      case 'entering':{
        if(e.delay>0){e.delay--;e.x=-40;e.y=-40;break;}
        e.d+=e.speed;
        const q=e.path.at(e.d);e.x=q.x;e.y=q.y;
        if(Math.random()<0.0008+stage*0.0004)fireEB(e.x,e.y+6,Math.random()<0.5);
        if(e.d>=e.path.len)e.state='formation';
        break;}
      case 'formation':{
        const s=slotXY(e.row,e.col);e.x=s.x;e.y=s.y;
        // occasional formation shot (rare, more with stage)
        e.fireT--;
        if(e.fireT<=0&&G.eBullets.length<5&&Math.random()<0.02+stage*0.01){
          fireEB(e.x,e.y+6,Math.random()<0.4);e.fireT=200+((Math.random()*300)|0);
        }
        break;}
      case 'diving':{
        e.d+=2.4+stage*0.05;
        const q=e.path.at(e.d);e.x=q.x;e.y=q.y;
        e.fireT--;
        if(e.fireT<=0&&e.y<H-60){fireEB(e.x,e.y+6,true);e.fireT=25+((Math.random()*35)|0);}
        if(e.d>=e.path.len){ // left bottom -> re-enter from top
          e.state='reentry';e.d=0;
          const rx=Math.max(20,Math.min(W-20,e.x));
          const slot=slotXY(e.row,e.col);
          e.path=makePath([{x:rx,y:-16},{x:rx,y:30},{x:slot.x,y:slot.y}]);
        }
        break;}
      case 'escort':{
        const b=e.boss;
        if(b.dead){startDive(e,'attack');break;}
        e.x=b.x+e.off.x;e.y=b.y+e.off.y;
        if(e.y>H+10){e.state='reentry';e.d=0;
          const slot=slotXY(e.row,e.col);
          e.path=makePath([{x:e.x,y:-16},{x:slot.x,y:40},{x:slot.x,y:slot.y}]);}
        break;}
      case 'reentry':{
        e.d+=2.2;
        const q=e.path.at(e.d);e.x=q.x;e.y=q.y;
        if(e.d>=e.path.len)e.state='formation';
        break;}
      case 'beamDive':{
        e.d+=2.2;
        const q=e.path.at(e.d);e.x=q.x;e.y=q.y;
        if(e.d>=e.path.len){
          e.state='beam';e.beamT=0;
          if(!G.beam){G.beam={boss:e,phase:0,t:0};sBeamStart();}
          else e.state='return'; // another beam already active
        }
        break;}
      case 'beam':{
        // held in place; beam handled in updateBeam
        break;}
      case 'return':{
        if(!e.retPath){
          e.retPath=makePath([{x:e.x,y:e.y},{x:e.x,y:e.y-25},
            {x:FMT_CX+(e.col-4.5)*COLS,y:FMT_TOP+e.row*ROWS}]);
          e.d=0;
        }
        e.d+=2.4;
        const q=e.retPath.at(e.d);e.x=q.x;e.y=q.y;
        if(e.d>=e.retPath.len){e.state='formation';e.retPath=null;}
        break;}
    }
    // captive fighter fires while its boss dives
    if(e.type==='boss'&&e.captive&&(e.state==='diving'||e.state==='beam'||e.state==='beamDive')){
      e.captiveFireT=(e.captiveFireT||40)-1;
      if(e.captiveFireT<=0){fireEB(e.x,e.y-8,true);e.captiveFireT=45+((Math.random()*40)|0);}
    }
  }
  // remove dead, free escorts
  G.enemies=G.enemies.filter(e=>!e.dead);
}

/* ---- tractor beam ---- */
function updateBeam(){
  const b=G.beam,p=G.player;
  if(!b)return;
  const boss=b.boss;
  if(boss.dead){G.beam=null;sBeamStop();boss.state='return';return;}
  b.t++;
  if(b.phase===0&&b.t>45){b.phase=1;b.t=0;}
  else if(b.phase===1&&b.t>150){b.phase=2;b.t=0;}
  else if(b.phase===2&&b.t>30){
    G.beam=null;sBeamStop();boss.state='return';return;
  }
  // capture check while fully extended
  if(b.phase===1&&p.alive&&!p.captured&&p.invul<=0){
    const topY=boss.y+6,py=p.y;
    const f=(py-topY)/(H-topY);
    const halfW=3+f*20;
    if(Math.abs(p.x-boss.x)<halfW){
      p.captured=true;p.captureT=0;p.captureBoss=boss;
      G.beam=null;sBeamStop();boss.state='return';
      sCapture();
    }
  }
}

/* ---- captured fighter (freed / hostile) ---- */
function updateShips(){
  const p=G.player;
  for(const s of G.ships){
    if(s.dead)continue;s.t++;
    if(s.state==='freed'){
      if(s.t<40){s.y+=0.6;}
      else{
        s.vy=1.6;s.y+=s.vy;
        s.x+=Math.max(-1.5,Math.min(1.5,(p.x-s.x)*0.05));
        if(s.y>=p.y-2&&p.alive&&!p.dual&&!p.captured){
          p.dual=true;p.x=Math.max(16,Math.min(W-16,(p.x+s.x)/2));
          p.invul=Math.max(p.invul,60);s.dead=true;sDock();
        }
      }
      if(s.y>H+12)s.dead=true;
    }else if(s.state==='hostile'){
      s.vy=Math.min(1.6,s.vy+0.05);s.y+=s.vy;
      s.fireT--;
      if(s.fireT<=0&&s.y<H-40){fireEB(s.x,s.y+6,true);s.fireT=60;}
      if(s.y>H+12)s.dead=true;
    }
  }
  G.ships=G.ships.filter(s=>!s.dead);
}

/* ---- player ---- */
function updatePlayer(){
  const p=G.player;
  if(p.fireCd>0)p.fireCd--;
  if(p.invul>0)p.invul--;

  if(p.captured){
    // being dragged up into the boss
    const b=p.captureBoss;
    p.captureT++;
    const tx=b.x,ty=b.y-14;
    p.x+=(tx-p.x)*0.08;p.y+=(ty-p.y)*0.08;
    if(p.captureT>25&&Math.hypot(tx-p.x,ty-p.y)<3)finishCapture(b);
    return;
  }
  if(!p.alive)return;

  const L=keys['ArrowLeft']||keys['a']||keys['A'];
  const R=keys['ArrowRight']||keys['d']||keys['D'];
  const v=2.1;
  if(L&&!R)p.x-=v;
  if(R&&!L)p.x+=v;
  const half=p.dual?15:7;
  p.x=Math.max(half,Math.min(W-half,p.x));
  if(keys[' '])playerFire();

  // enemy bullets vs player
  for(const b of G.eBullets){
    if(b.dead)continue;
    if(hitPlayer(b.x,b.y,2,3)){
      b.dead=true;playerHit(b.x,b.y);
    }
  }
  // enemy bodies vs player
  if(p.invul<=0){
    for(const e of G.enemies){
      if(e.dead||e.state==='entering'&&e.y<0)continue;
      const hw=e.type==='boss'?7:6,hh=e.type==='boss'?6:5;
      if(Math.abs(e.x-p.x)<hw+6&&Math.abs(e.y-p.y)<hh+6){
        const pts=enemyScore(e);
        killEnemy(e,true);
        playerHit(e.x,e.y);
        break;
      }
    }
  }
  G.eBullets=G.eBullets.filter(b=>!b.dead);
}
function hitPlayer(x,y,hw,hh){
  const p=G.player;
  if(!p.alive||p.captured||p.invul>0)return false;
  const test=cx=>Math.abs(x-cx)<hw+5&&Math.abs(y-p.y)<hh+6;
  if(p.dual)return test(p.x-8)||test(p.x+8);
  return test(p.x);
}
function playerHit(){
  const p=G.player;
  if(p.invul>0||!p.alive||p.captured)return;
  if(p.dual){ // lose one half, keep flying
    p.dual=false;p.invul=90;
    addExpl(p.x+((Math.random()<0.5)?-8:8),p.y,false);
    sPlayerDie();
  }else{
    sPlayerDie();
    addExpl(p.x,p.y,true);
    p.alive=false;p.respawnT=100;
    loseLife();
  }
}

/* ---- bullets ---- */
function updateBullets(){
  for(const b of G.pBullets){
    if(b.dead)continue;
    b.y-=4.2;
    if(b.y<-6){b.dead=true;continue;}
    for(const e of G.enemies){
      if(e.dead||e.y<4)continue;
      const hw=e.type==='boss'?7:6,hh=e.type==='boss'?6:5;
      if(Math.abs(b.x-e.x)<hw&&Math.abs(b.y-e.y)<hh){
        b.dead=true;
        if(e.type==='boss'&&e.hp>1){e.hp=1;sBossHit();G.hits++;}
        else killEnemy(e,true);
        break;
      }
    }
    // player shots can also destroy hostile/freed captive fighters
    for(const s of G.ships){
      if(s.dead||s.state!=='hostile')continue;
      if(Math.abs(b.x-s.x)<6&&Math.abs(b.y-s.y)<6){b.dead=true;s.dead=true;addExpl(s.x,s.y,false);score(100);sEnemyDie();break;}
    }
  }
  G.pBullets=G.pBullets.filter(b=>!b.dead);
  for(const b of G.eBullets){b.y+=b.vy;b.x+=b.vx;if(b.y>H+8||b.y<-8||b.x<-8||b.x>W+8)b.dead=true;}
  G.eBullets=G.eBullets.filter(b=>!b.dead);
}

/* ---- challenging stage ---- */
function spawnChallengeWave(){
  G.chWave++;G.chWaveActive=true;G.chWaveHits=0;G.chWaveDone=0;
  const dir=G.chWave%2===1?1:-1;
  for(let i=0;i<8;i++){
    const e={type:'zako',row:0,col:0,state:'challenge',d:0,speed:2.6,
      x:-40,y:-40,ft:i*3,delay:i*9,path:challengePath(dir,i),hp:1,dead:false};
    G.enemies.push(e);
  }
}
function updateChallenge(){
  const p=G.player;p.fireCd>0&&p.fireCd--;
  if(p.invul>0)p.invul--;
  const L=keys['ArrowLeft']||keys['a']||keys['A'],R=keys['ArrowRight']||keys['d']||keys['D'];
  if(L&&!R)p.x-=2.1;if(R&&!L)p.x+=2.1;
  p.x=Math.max(7,Math.min(W-7,p.x));
  if(keys[' '])playerFire();
  updateBullets();
  for(const e of G.enemies){
    if(e.dead)continue;
    if(e.delay>0){e.delay--;continue;}
    e.ft++;e.d+=e.speed;
    const q=e.path.at(e.d);e.x=q.x;e.y=q.y;
    if(e.d>=e.path.len)e.dead=true;
    // ramming still hurts
    if(p.alive&&p.invul<=0&&Math.abs(e.x-p.x)<10&&Math.abs(e.y-p.y)<9){
      e.dead=true;G.chWaveHits++;G.chHits++;addExpl(e.x,e.y,false);sEnemyDie();playerHit();
    }
  }
  G.enemies=G.enemies.filter(e=>!e.dead);
  for(const x of G.expl)x.t++;
  G.expl=G.expl.filter(x=>x.t<20);
  if(G.chWaveActive&&G.enemies.length===0){
    G.chWaveActive=false;
    if(G.chWaveHits===8){G.chBonus+=1000;score(1000);}
    if(G.chWave>=5){
      if(G.chHits===40){G.chBonus+=10000;score(10000);}
      G.mode='chresult';G.overlayT=0;
    }else{
      G.chDelay=90;
    }
  }else if(!G.chWaveActive&&G.chWave<5){
    G.chDelay--;
    if(G.chDelay<=0)spawnChallengeWave();
  }
  respawnCheck();
}

/* ================= rendering ================= */
function drawExpl(x,y,t,big){
  const f=Math.floor(t/(big?1.5:1));
  const n=big?16:10,maxR=big?14:9;
  const r=Math.min(maxR,f*0.9+1);
  const cols=['#ffffff','#ffd23b','#ff8b2b','#ff3b3b'];
  ctx.fillStyle=cols[Math.min(3,Math.floor(f/4))];
  for(let i=0;i<n;i++){
    const a=i*2.399963; // golden-angle spread
    const rr=r*(0.55+0.45*Math.abs(Math.sin(i*7.3)));
    if(f>maxR&&i%3===0)continue;
    ctx.fillRect(Math.round(x+Math.cos(a)*rr),Math.round(y+Math.sin(a)*rr),2,2);
  }
}
function enemySprite(e){
  const flap=(Math.floor(e.ft/8)%2)===0;
  if(e.type==='zako')return flap?'zakoA':'zakoB';
  if(e.type==='goei')return flap?'goeiA':'goeiB';
  return flap?'bossA':'bossB';
}
function enemyVariant(e){return(e.type==='boss'&&e.hp===1)?'bossDmg':null;}

function drawEnemies(){
  for(const e of G.enemies){
    if(e.state==='entering'&&e.delay>0)continue;
    blit(enemySprite(e),e.x,e.y,enemyVariant(e));
    if(e.type==='boss'&&e.captive)blit('player',e.x,e.y-14,'playerBoss');
  }
}
function drawShips(){
  for(const s of G.ships)blit('player',s.x,s.y,'playerBoss');
}
function drawBeam(){
  const b=G.beam;if(!b)return;
  const boss=b.boss;
  const topY=boss.y+6;
  let len=H-topY;
  if(b.phase===0)len*=b.t/45;
  if(b.phase===2)len*=(1-b.t/30);
  if(len<=0)return;
  const halfTop=3,halfBot=3+((len)/(H-topY))*20;
  for(let yy=0;yy<len;yy+=2){
    const f=yy/(H-topY);
    const hw=halfTop+(halfBot-halfTop)*f;
    const jag=Math.sin(yy*0.6+G.t*0.5)*1.5;
    const c=(Math.floor(yy/4+G.t*0.5)%3===0)?'#3befff':(Math.floor(yy/4+G.t*0.5)%3===1?'#3838ff':'#ffffff');
    ctx.fillStyle=c;
    ctx.globalAlpha=0.75;
    ctx.fillRect(Math.round(boss.x-hw+jag),Math.round(topY+yy),Math.round(hw*2),2);
  }
  ctx.globalAlpha=1;
}
function drawPlayer(){
  const p=G.player;
  if(G.mode==='play'&&(!p.alive||p.captured))return;
  if(p.invul>0&&Math.floor(G.t/4)%2===0)return; // blink while invulnerable
  if(p.dual){blit('player',p.x-8,p.y);blit('player',p.x+8,p.y);}
  else blit('player',p.x,p.y);
}
function drawBullets(){
  ctx.fillStyle='#ffffff';
  for(const b of G.pBullets)ctx.fillRect(b.x-1,b.y-4,2,6);
  ctx.fillStyle='#3befff';
  for(const b of G.eBullets)ctx.fillRect(b.x-1,b.y-3,3,7);
  ctx.fillStyle='#ffffff';
  for(const b of G.eBullets)ctx.fillRect(b.x-1,b.y-3,1,3);
}
function drawExplosions(){for(const x of G.expl)drawExpl(x.x,x.y,x.t,x.big);}

/* stage badges: arcade denominations 50,30,20,10,5,1 */
function flagList(n){
  const out=[],den=[50,30,20,10,5,1];
  for(const d of den)while(n>=d){out.push(d);n-=d;}
  return out;
}
function drawHUD(){
  drawText('1UP',24,2,'#ff3b3b');
  drawText('HIGH SCORE',80,2,'#ff3b3b');
  drawText(String(G.score).padStart(6,'0'),24,11,'#ffffff');
  drawText(String(G.hi).padStart(6,'0'),88,11,'#ffffff');
